78	function resolveStandaloneAgent(): AiRuntimeDetails | null {
79	  const result = spawnSync("which", ["pi"], { encoding: "utf8", env: process.env });
80	  if (result.status === 0 && result.stdout.trim()) {
81	    const command = result.stdout.trim();
82	    const versionResult = spawnSync(command, ["--version"], { encoding: "utf8", env: process.env });
83	    if (versionResult.status === 0 && /^\d+\.\d+\.\d+/.test(versionResult.stdout.trim())) {
84	      return {
85	        kind: "binary",
86	        command
87	      };
88	    }
89	  }
90	  return null;
91	}
