108	async function syncZyphraProvider(cwd: string, env: NodeJS.ProcessEnv): Promise<void> {
109	  if (!env.ZYPHRA_API_KEY) return;
110	
111	  const modelsPath = join(configDir(cwd), "models.json");
112	  let existing: Record<string, unknown> = {};
113	  try {
114	    const raw = await readFile(modelsPath, "utf8");
115	    const parsed = JSON.parse(raw);
116	    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
117	      existing = parsed as Record<string, unknown>;
118	    }
119	  } catch {
120	    existing = {};
121	  }
122	
123	  const providers = (existing.providers as Record<string, unknown>) ?? {};
124	  const merged = { ...existing, providers: { ...providers, zyphra: ZYPHRA_PI_PROVIDER } };
125	  await mkdir(configDir(cwd), { recursive: true });
126	  await writeFile(modelsPath, `${JSON.stringify(merged, null, 2)}\n`, "utf8");
127	}
