129	async function syncPiSettings(cwd: string, config: KeatingConfig): Promise<void> {
130	  const agentDir = configDir(cwd);
131	  const settingsPath = join(agentDir, "settings.json");
132	  let settings: Record<string, unknown> = {};
133	
134	  try {
135	    const parsed = JSON.parse(await readFile(settingsPath, "utf8"));
136	    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
137	      settings = parsed as Record<string, unknown>;
138	    }
139	  } catch {
140	    settings = {};
141	  }
142	
143	  const quietStartup = !config.debug.consoleSummary;
144	  const nextSettings: Record<string, unknown> = { ...settings, quietStartup };
145	  if (Array.isArray(config.pi.packages)) {
146	    nextSettings.packages = normalizePiPackages(config.pi.packages);
147	  }
148	  if (JSON.stringify(settings) === JSON.stringify(nextSettings)) return;
149	
150	  await mkdir(agentDir, { recursive: true });
151	  await writeFile(settingsPath, `${JSON.stringify(nextSettings, null, 2)}\n`, "utf8");
152	}
