162	function hasFlag(args: string[], flag: string): boolean {
163	  return args.includes(flag) || args.some((arg) => arg.startsWith(`${flag}=`));
164	}
165	
166	function flagValue(args: string[], flag: string): string | undefined {
167	  const equalsArg = args.find((arg) => arg.startsWith(`${flag}=`));
168	  if (equalsArg) return equalsArg.slice(flag.length + 1);
169	  const index = args.indexOf(flag);
170	  return index >= 0 ? args[index + 1] : undefined;
171	}
