173	function selectAuthenticatedProvider(cwd: string, config: KeatingConfig, args: string[]): ProviderAuthSelection {
174	  const env = envWithProviderAliases(process.env);
175	  if (hasFlag(args, "--list-models") || hasFlag(args, "--list-providers")) return { env };
176	
177	  const hasExplicitProvider = hasFlag(args, "--provider");
178	  const hasExplicitModel = hasFlag(args, "--model");
179	  const hasExplicitApiKey = hasFlag(args, "--api-key");
180	  const configuredProvider = config.pi.defaultProvider ?? DEFAULT_PI_PROVIDER;
181	
182	  if (hasExplicitProvider) {
183	    const provider = flagValue(args, "--provider");
184	    if (provider && !hasExplicitApiKey && PROVIDER_ENV_KEYS[provider] && !providerIsConfigured(cwd, env, provider)) {
185	      return { env, note: providerSetupMessage(provider), missingProvider: provider };
186	    }
187	    return { env };
188	  }
189	
190	  const candidates = [configuredProvider, "google", "openai", "anthropic", "openrouter", "zyphra"].filter((provider, index, all) =>
191	    provider && all.indexOf(provider) === index
192	  );
193	  const selected = candidates.find((provider) => providerIsConfigured(cwd, env, provider));
194	  if (!selected) {
195	    return {
196	      env,
197	      missingProvider: configuredProvider,
198	      note: [
199	      providerSetupMessage(configuredProvider),
200	      "",
201	      "Keating also checked for OpenAI, Anthropic, OpenRouter, and Zyphra credentials and did not find them.",
202	      "Supported fallback env vars:",
203	      "  GEMINI_API_KEY or GOOGLE_API_KEY",
204	      "  OPENAI_API_KEY",
205	      "  ANTHROPIC_API_KEY or ANTHROPIC_OAUTH_TOKEN",
206	      "  OPENROUTER_API_KEY (free models available at https://openrouter.ai)",
207	      "  ZYPHRA_API_KEY (ZAYA1-8B via https://cloud.zyphra.com)"
208	    ].join("\n")
209	    };
210	  }
211	
212	  if (selected === configuredProvider) return { env };
213	
214	  return {
215	    provider: selected,
216	    model: hasExplicitModel ? undefined : FALLBACK_PI_MODELS[selected],
217	    env,
218	    note: `No credentials found for "${configuredProvider}". Using configured ${selected} credentials instead.`
219	  };
220	}
