222	function resolveAgentInNodeModules(nodeModulesDir: string): AiRuntimeDetails | null {
223	  for (const [scope, pkg] of CLI_AGENT_PACKAGES) {
224	    const cliPath = join(nodeModulesDir, scope, pkg, "dist", "cli.js");
225	    if (existsSync(cliPath)) {
226	      return { kind: "embedded-keating", command: process.execPath, cliPath };
227	    }
228	  }
229	
230	  return null;
231	}
