233	async function resolveEmbeddedAgent(packageRoot = resolvePackageRoot()): Promise<AiRuntimeDetails | null> {
234	  const local = resolveAgentInNodeModules(join(packageRoot, "node_modules"));
235	  if (local) return local;
236	
237	  const base = join(homedir(), ".local", "share", "keating");
238	  const entries = await readdir(base, { withFileTypes: true }).catch(() => []);
239	  const dirs = entries
240	    .filter((entry: any) => entry.isDirectory())
241	    .map((entry: any) => entry.name)
242	    .sort()
243	    .reverse();
244	
245	  for (const name of dirs) {
246	    for (const root of [join(base, name), join(base, name, "app")]) {
247	      const embedded = resolveAgentInNodeModules(join(root, "node_modules"));
248	      if (embedded) return embedded;
249	    }
250	  }
251	
252	  for (const [scope, pkg] of CLI_AGENT_PACKAGES) {
253	    const globalPrefix = join(homedir(), ".local", "share", "mise", "installs", "node");
254	    const versionEntries = await readdir(globalPrefix, { withFileTypes: true }).catch(() => []);
255	    const versionDirs = versionEntries
256	      .filter((e: any) => e.isDirectory())
257	      .map((e: any) => e.name)
258	      .sort()
259	      .reverse();
260	
261	    for (const ver of versionDirs) {
262	      const cliPath = join(globalPrefix, ver, "lib", "node_modules", scope, pkg, "dist", "cli.js");
263	      if (existsSync(cliPath)) {
264	        return { kind: "embedded-keating", command: process.execPath, cliPath };
265	      }
266	      const nmDir = join(globalPrefix, ver, "lib", "node_modules");
267	      const nmEntries = await readdir(nmDir, { withFileTypes: true }).catch(() => []);
268	      const nmDirs = nmEntries.filter((e: any) => e.isDirectory() || (e.isSymbolicLink() && (() => { try { return statSync(join(nmDir, e.name)).isDirectory(); } catch { return false; } })()));
269	      for (const nmEntry of nmDirs) {
270	        const nested = join(nmDir, nmEntry.name, "node_modules", scope, pkg, "dist", "cli.js");
271	        if (existsSync(nested)) {
272	          return { kind: "embedded-keating", command: process.execPath, cliPath: nested };
273	        }
274	      }
275	    }
276	
277	    const bunGlobal = join(homedir(), ".bun", "install", "global", "node_modules", scope, pkg, "dist", "cli.js");
278	    if (existsSync(bunGlobal)) {
279	      return { kind: "embedded-keating", command: process.execPath, cliPath: bunGlobal };
280	    }
281	  }
282	
283	  return null;
284	}
