286	export async function detectAiRuntime(cwd: string): Promise<AiRuntimeReport> {
287	  const config = await loadKeatingConfig(cwd);
288	  const standalone = resolveStandaloneAgent();
289	  const embedded = await resolveEmbeddedAgent();
290	
291	  let selected: AiRuntimeDetails | null = null;
292	  switch (config.pi.runtimePreference) {
293	    case "embedded-only":
294	      selected = embedded;
295	      break;
296	    case "prefer-standalone":
297	      selected = standalone ?? embedded;
298	      break;
299	    case "standalone-only":
300	    default:
301	      selected = standalone;
302	      break;
303	  }
304	
305	  return {
306	    selected,
307	    standalone,
308	    embedded,
309	    preference: config.pi.runtimePreference
310	  };
311	}
