384	          env: {
385	            ...authSelection.env,
386	            KEATING_AUTH_MISSING_PROVIDER: authSelection.missingProvider ?? "",
387	            PI_SKIP_VERSION_CHECK: process.env.PI_SKIP_VERSION_CHECK ?? "1",
388	            PI_CODING_AGENT_DIR: configDir(cwd)
389	          }
390	        });
391	
392	  return await new Promise<number>((resolvePromise, reject) => {
393	    child.on("error", reject);
394	    child.on("exit", (code: number | null) => resolvePromise(code ?? 0));
395	  });
