398	/**
399	 * Start the same configured Pi runtime as `keating shell`, but over the
400	 * headless RPC transport so alternate hosts can render it. The caller owns
401	 * the returned client's lifecycle and must call `stop()`.
402	 */
403	export async function launchRpcClient(cwd: string, args: string[] = []): Promise<RpcClient> {
404	  await ensureProjectScaffold(cwd);
405	  const config = await loadKeatingConfig(cwd);
406	  await syncPiSettings(cwd, config);
407	  await syncZyphraProvider(cwd, process.env);
408	
409	  const report = await detectAiRuntime(cwd);
410	  const runtime = report.selected;
411	  if (!runtime) throw new Error(missingRuntimeMessage(report));
412	
413	  const packageRoot = resolvePackageRoot();
414	  const isDist = __dirname.replace(/\\/g, "/").includes("/dist/src/runtime");
415	  const extensionPath = isDist
416	    ? join(__dirname, "..", "pi", "hyper-teacher", "index.js")
417	    : join(packageRoot, "dist", "src", "pi", "hyper-teacher", "index.js");
418	  if (!existsSync(extensionPath)) {
419	    throw new Error(`Missing built extension: ${extensionPath}. Run bun run build before keating tui.`);
420	  }
421	
422	  const promptDir = join(packageRoot, "pi", "prompts");
423	  const skillsDir = join(packageRoot, "pi", "skills");
424	  const systemPrompt = readFileSync(join(packageRoot, "SYSTEM.md"), "utf8");
425	  const authSelection = selectAuthenticatedProvider(cwd, config, args);
426	  if (authSelection.note) console.error(authSelection.note);
427	
428	  const sharedArgs = mergePiDefaultsWithOverrides(config, [
429	    "--session-dir",
430	    sessionsDir(cwd),
431	    "--extension",
432	    extensionPath,
433	    "--prompt-template",
434	    promptDir,
435	    "--skill",
436	    skillsDir,
437	    "--append-system-prompt",
438	    systemPrompt,
439	    "--tools",
440	    "read,bash,edit,write,grep,find,ls",
441	    ...args,
442	  ], { provider: authSelection.provider, model: authSelection.model });
443	
444	  const cliPath = runtime.cliPath ?? runtime.command;
445	  const client = new RpcClient({
446	    cliPath,
447	    cwd,
448	    args: sharedArgs,
449	    env: {
450	      ...authSelection.env,
451	      KEATING_AUTH_MISSING_PROVIDER: authSelection.missingProvider ?? "",
452	      PI_SKIP_VERSION_CHECK: process.env.PI_SKIP_VERSION_CHECK ?? "1",
453	      PI_CODING_AGENT_DIR: configDir(cwd),
454	    } as Record<string, string>,
455	  });
456	  await client.start();
457	  return client;
458	}
