39	export function envWithProviderAliases(env: NodeJS.ProcessEnv): NodeJS.ProcessEnv {
40	  if (!env.GEMINI_API_KEY && env.GOOGLE_API_KEY) {
41	    return { ...env, GEMINI_API_KEY: env.GOOGLE_API_KEY };
