46	export function authJsonHasProvider(cwd: string, provider: string): boolean {
47	  const path = join(configDir(cwd), "auth.json");
48	  try {
49	    const parsed = JSON.parse(readFileSync(path, "utf8")) as Record<string, unknown>;
50	    return Boolean(parsed?.[provider]);
51	  } catch {
52	    return false;
53	  }
54	}
