154	        const details = result?.details;
155	        if (!details?.quiz) return undefined;
156	        const answers = details.answers ? new Map<string, string>(Object.entries(details.answers)) : undefined;
157	        const objectiveResults = details.objectiveResults ? new Map<string, boolean>(Object.entries(details.objectiveResults)) : undefined;
