165	    "Grade the open-ended (short_answer/transfer) questions from a prior quiz tool call. Call after the quiz tool returns a result_id for open-ended grading.",
166	    {
167	      result_id: { type: "string", description: "The result_id returned by the quiz tool." },
168	      grades: {
169	        type: "array",
