171	        items: {
172	          type: "object",
173	          properties: {
174	            question_id: { type: "string" },
175	            verdict: { type: "string", enum: ["correct", "incorrect", "partial"] },
176	            note: { type: "string" }
177	          },
178	          required: ["question_id", "verdict"]
179	        }
180	      }
181	    },
182	    async (params) => {
183	      const resultId = (params.result_id as string) || "";
184	      const pending = pendingQuizResults.get(resultId);
185	      if (!pending) return { content: [{ type: "text", text: `No pending quiz result found for result_id "${resultId}".` }] };
186	
187	      const gradesInput = Array.isArray(params.grades) ? params.grades : [];
188	      const openEndedGrades: Record<string, { verdict: "correct" | "incorrect" | "partial"; note?: string }> = {};
189	      for (const g of gradesInput) {
