192	        const verdict = (g as Record<string, unknown>).verdict;
193	        if (typeof questionId !== "string" || (verdict !== "correct" && verdict !== "incorrect" && verdict !== "partial")) continue;
194	        const note = (g as Record<string, unknown>).note;
