210	      return {
211	        content: [{ type: "text", text: `Final quiz score: ${objectiveCorrect + openEndedCorrect}/${objectiveTotal + openEndedTotal}.` }],
212	        details: { quiz: pending.quiz, answers: pending.answers, objectiveResults: pending.objectiveResults, openEndedGrades }
213	      };
214	    },
