27	/** A static (non-interactive) bordered card, matching the visual style of createKeatingHeaderComponent. */
28	export function renderCard(theme: Theme, heading: string, bodyLines: string[]): Component {
29	  const t = theme.fg.bind(theme);
30	  const b = theme.bold.bind(theme);
31	  const border = (text: string) => t("borderMuted", text);
32	  const headingText = b(t("mdHeading", heading));
33	
34	  return {
35	    render(width: number): string[] {
36	      const cardWidth = Math.min(Math.max(width - 2, 20), 100);
37	      const innerWidth = cardWidth - 4;
38	      const lines: string[] = [];
39	      lines.push(border(`╭${"─".repeat(cardWidth - 2)}╮`));
40	      lines.push(`${border("│")} ${pad(headingText, innerWidth)} ${border("│")}`);
41	      lines.push(`${border("├")}${border("─".repeat(cardWidth - 2))}${border("┤")}`);
42	      for (const raw of bodyLines) {
43	        const wrapped = raw.length === 0 ? [""] : wrap(raw, innerWidth);
44	        for (const line of wrapped) {
45	          lines.push(`${border("│")} ${pad(line, innerWidth)} ${border("│")}`);
46	        }
47	      }
48	      lines.push(border(`╰${"─".repeat(cardWidth - 2)}╯`));
49	      return lines;
50	    },
51	    invalidate() {},
52	  };
53	}
