55	/** Reads a just-written artifact file from disk and renders it as a bordered markdown preview. */
56	export function renderArtifactPreview(theme: Theme, title: string, filePath: string, maxLines = 40): Component {
57	  let bodyLines: string[];
58	  try {
59	    const raw = readFileSync(filePath, "utf8");
60	    const allLines = raw.split("\n");
61	    bodyLines = allLines.slice(0, maxLines);
62	    if (allLines.length > maxLines) {
63	      bodyLines.push("", `… ${allLines.length - maxLines} more lines (see ${filePath})`);
64	    }
65	  } catch {
66	    bodyLines = [`(could not read ${filePath})`];
67	  }
68	  return renderCard(theme, title, bodyLines);
69	}
