71	const QUESTION_STATUS_GLYPH: Record<"unanswered" | "answered" | "correct" | "incorrect" | "pending_grade", string> = {
72	  unanswered: "○",
73	  answered: "●",
74	  correct: "✓",
75	  incorrect: "✗",
76	  pending_grade: "…",
