79	export interface QuizCardState {
80	  answers?: Map<string, string>;
81	  objectiveResults?: Map<string, boolean>;
82	  openEndedGrades?: Map<string, { verdict: "correct" | "incorrect" | "partial"; note?: string }>;
83	}
84	
85	function questionStatus(q: QuizQuestion, state: QuizCardState): keyof typeof QUESTION_STATUS_GLYPH {
86	  const graded = state.openEndedGrades?.get(q.id);
87	  if (graded) return graded.verdict === "partial" ? "answered" : graded.verdict;
88	  const objective = state.objectiveResults?.get(q.id);
89	  if (objective !== undefined) return objective ? "correct" : "incorrect";
90	  const isOpenEnded = q.type === "short_answer" || q.type === "transfer";
91	  if (isOpenEnded && state.answers?.has(q.id)) return "pending_grade";
92	  return state.answers?.has(q.id) ? "answered" : "unanswered";
93	}
