95	export function renderQuizCard(theme: Theme, quiz: Quiz, state: QuizCardState = {}): Component {
96	  const lines: string[] = [];
97	  let correct = 0;
98	  let graded = 0;
99	  for (const q of quiz.questions) {
100	    const status = questionStatus(q, state);
101	    if (status === "correct") correct++;
102	    if (status === "correct" || status === "incorrect") graded++;
103	    lines.push(`${QUESTION_STATUS_GLYPH[status]} [${q.level}] ${q.question}`);
104	    const answer = state.answers?.get(q.id);
105	    if (answer) lines.push(`   your answer: ${answer}`);
106	    const note = state.openEndedGrades?.get(q.id)?.note;
107	    if (note) lines.push(`   feedback: ${note}`);
108	  }
109	  if (graded > 0) {
110	    lines.unshift("", `Objective score: ${correct}/${graded}`);
111	  }
112	  return renderCard(theme, `Quiz: ${quiz.topic}`, lines);
113	}
