115	function progressBar(percent: number, width = 20): string {
116	  const filled = Math.round((Math.max(0, Math.min(100, percent)) / 100) * width);
117	  return `[${"#".repeat(filled)}${"-".repeat(width - filled)}] ${percent}%`;
118	}
