126	export function renderGoalCard(theme: Theme, goal: LearnerGoal): Component {
127	  const total = goal.steps.length;
128	  const done = goal.steps.filter((s) => s.status === "done").length;
129	  const percent = total === 0 ? 0 : Math.round((done / total) * 100);
130	  const nextStep = goal.steps.find((s) => s.status !== "done");
131	
132	  const lines: string[] = [];
133	  if (goal.description) lines.push(goal.description, "");
134	  lines.push(`Progress: ${progressBar(percent)} (${done}/${total})`, `Status: ${goal.status}`);
135	  if (nextStep) lines.push(`Next: ${nextStep.title}`);
136	  lines.push("");
137	  for (const step of goal.steps) {
138	    lines.push(`${GOAL_STEP_GLYPH[step.status] ?? "[ ]"} ${step.order + 1}. ${step.title} (${step.kind})`);
139	  }
140	  return renderCard(theme, `Goal: ${goal.title}`, lines);
141	}
