154	
155	export type AnswerFormKind = "choice" | "text" | "blanks" | "classification" | "matching";
156	
157	export interface AnswerFormQuestion {
158	  id: string;
159	  prompt: string;
160	  kind: AnswerFormKind;
161	  choices?: string[];
162	  items?: string[];
163	  allowText?: boolean;
164	  requireReasons?: boolean;
165	  uniqueMatches?: boolean;
166	}
167	
168	export interface AnswerFormResult {
169	  [questionId: string]: string;
170	}
171	
172	const OTHER_ITEM_VALUE = "__answer_form_other__";
173	
174	/**
175	 * A blocking, keyboard-driven form. Renders one or more questions vertically;
176	 * only the focused row receives keystrokes. Supports choice (SelectList),
177	 * free text (Input), and per-row choice sequences for classification/matching
178	 * (one SelectList + optional reason Input per item/row).
179	 */
180	interface FormRow {
181	  questionId: string;
182	  label: string;
183	  control: SelectList | Input;
184	  /** A follow-up Input shown after `control` is confirmed (e.g. a classification reason, or free text for "Other"). */
185	  followUpControl?: Input;
186	  /** "always": ask the follow-up regardless of the primary selection. "on-other": only when OTHER_ITEM_VALUE was picked. */
187	  followUpTrigger?: "always" | "on-other";
188	}
189	
190	export class AnswerFormComponent implements Component {
191	  private theme: Theme;
192	  private questions: AnswerFormQuestion[];
193	  private rows: FormRow[] = [];
194	  private focusIndex = 0;
195	  /** true once the focused row's primary control is confirmed and its reasonControl (if any) is active. */
196	  private onReasonStep = false;
197	  private answers = new Map<string, string>();
198	  private done: (result: AnswerFormResult) => void;
199	  invalidate: () => void = () => {};
200	
201	  constructor(theme: Theme, questions: AnswerFormQuestion[], done: (result: AnswerFormResult) => void) {
202	    this.theme = theme;
203	    this.questions = questions;
204	    this.done = done;
205	    this.buildRows();
206	  }
207	
208	  private buildRows(): void {
209	    const selectTheme = getSelectListTheme();
210	    for (const q of this.questions) {
211	      if (q.kind === "choice" && q.choices && q.choices.length > 0) {
212	        const items: SelectItem[] = q.choices.map((c) => ({ value: c, label: c }));
213	        if (q.allowText) items.push({ value: OTHER_ITEM_VALUE, label: "Other (type your own answer)" });
214	        this.rows.push({
215	          questionId: q.id,
216	          label: q.prompt,
217	          control: new SelectList(items, 8, selectTheme),
218	          followUpControl: q.allowText ? new Input() : undefined,
219	          followUpTrigger: "on-other",
220	        });
221	      } else if (q.kind === "classification" || q.kind === "matching") {
222	        const rowItems = q.items ?? [];
223	        for (const [idx, item] of rowItems.entries()) {
224	          const choiceItems: SelectItem[] = (q.choices ?? []).map((c) => ({ value: c, label: c }));
225	          this.rows.push({
226	            questionId: `${q.id}::${idx}`,
227	            label: `${item} →`,
228	            control: new SelectList(choiceItems, 8, selectTheme),
229	            followUpControl: q.kind === "classification" && q.requireReasons ? new Input() : undefined,
230	            followUpTrigger: "always",
231	          });
232	        }
233	      } else {
234	        this.rows.push({ questionId: q.id, label: q.prompt, control: new Input() });
235	      }
236	    }
237	  }
238	
239	  private currentControl(): SelectList | Input | undefined {
240	    const row = this.rows[this.focusIndex];
241	    if (!row) return undefined;
242	    return this.onReasonStep && row.followUpControl ? row.followUpControl : row.control;
243	  }
244	
245	  private advance(): void {
246	    this.onReasonStep = false;
247	    if (this.focusIndex < this.rows.length - 1) {
248	      this.focusIndex += 1;
249	      this.invalidate();
250	    } else {
251	      this.done(Object.fromEntries(this.answers));
252	    }
253	  }
254	
255	  private confirmCurrentControl(): void {
256	    const row = this.rows[this.focusIndex];
257	    if (!row) return;
258	    if (!this.onReasonStep) {
259	      const value = row.control instanceof SelectList
260	        ? (row.control.getSelectedItem()?.value ?? "")
261	        : (row.control as Input).getValue();
262	      this.answers.set(row.questionId, value);
263	      const needsFollowUp =
264	        row.followUpControl &&
265	        (row.followUpTrigger === "always" || (row.followUpTrigger === "on-other" && value === OTHER_ITEM_VALUE));
266	      if (needsFollowUp) {
267	        this.onReasonStep = true;
268	        this.invalidate();
269	        return;
270	      }
271	      this.advance();
272	      return;
273	    }
274	    if (row.followUpControl) {
275	      const key = row.followUpTrigger === "on-other" ? row.questionId : `${row.questionId}::reason`;
276	      this.answers.set(key, row.followUpControl.getValue());
277	    }
278	    this.advance();
279	  }
280	
281	  handleInput(data: string): void {
282	    if (data === "\r" || data === "\n") {
283	      this.confirmCurrentControl();
284	      return;
285	    }
286	    if (data === "\x1b") {
287	      this.done(Object.fromEntries(this.answers));
288	      return;
289	    }
290	    this.currentControl()?.handleInput(data);
291	    this.invalidate();
292	  }
293	
294	  render(width: number): string[] {
295	    const t = this.theme.fg.bind(this.theme);
296	    const b = this.theme.bold.bind(this.theme);
297	    const lines: string[] = [];
298	    for (const q of this.questions) {
299	      lines.push(b(t("mdHeading", q.prompt)));
300	    }
301	    lines.push("");
302	    this.rows.forEach((row, idx) => {
303	      const isFocused = idx === this.focusIndex;
304	      const marker = isFocused ? t("accent", "▸ ") : "  ";
305	      lines.push(`${marker}${row.label}`);
306	      if (isFocused || this.answers.has(row.questionId)) {
307	        const controlLines = row.control.render(Math.max(10, width - 4));
308	        for (const line of controlLines) lines.push(`    ${line}`);
309	      }
310	      if (row.followUpControl && isFocused && this.onReasonStep) {
311	        lines.push(`    ${t("dim", row.followUpTrigger === "always" ? "reason:" : "your answer:")}`);
312	        for (const line of row.followUpControl.render(Math.max(10, width - 4))) lines.push(`    ${line}`);
313	      }
314	    });
315	    lines.push("", t("dim", "type or use arrow keys + Enter to confirm each row · Esc to submit early"));
316	    return lines;
317	  }
318	}
