import { readFileSync } from "node:fs";

/**
 * Theme-free card renderers shared by RPC hosts (keating tui, e2e tests).
 * The classic Pi shell keeps its themed equivalents in
 * src/pi/hyper-teacher/tui-components.ts; these emit plain strings so they
 * survive JSON transport and render in any terminal without pi-tui.
 *
 * Tool results that cross the RPC boundary are JSON-serialized, so Maps
 * (e.g. quiz.answerKey) arrive as plain objects or empty objects — every
 * accessor here tolerates both.
 */

const DEFAULT_CARD_WIDTH = 76;

function wrapPlain(text: string, width: number): string[] {
  const lines: string[] = [];
  for (const raw of text.split("\n")) {
    if (raw.length <= width) {
      lines.push(raw);
      continue;
    }
    let rest = raw;
    while (rest.length > width) {
      let cut = rest.lastIndexOf(" ", width);
      if (cut <= 0) cut = width;
      lines.push(rest.slice(0, cut));
      rest = rest.slice(cut).trimStart();
    }
    lines.push(rest);
  }
  return lines;
}

function padPlain(text: string, width: number): string {
  if (text.length > width) return width > 1 ? `${text.slice(0, width - 1)}…` : text.slice(0, width);
  return text + " ".repeat(width - text.length);
}

export function cardLines(heading: string, body: string[], width = DEFAULT_CARD_WIDTH): string[] {
  const cardWidth = Math.max(20, width);
  const innerWidth = cardWidth - 4;
  const lines: string[] = [];
  lines.push(`╭${"─".repeat(cardWidth - 2)}╮`);
  lines.push(`│ ${padPlain(heading, innerWidth)} │`);
  lines.push(`├${"─".repeat(cardWidth - 2)}┤`);
  for (const raw of body) {
    const wrapped = raw.length === 0 ? [""] : wrapPlain(raw, innerWidth);
    for (const line of wrapped) {
      lines.push(`│ ${padPlain(line, innerWidth)} │`);
    }
  }
  lines.push(`╰${"─".repeat(cardWidth - 2)}╯`);
  return lines;
}

export function artifactPreviewLines(title: string, filePath: string, maxLines = 40): string[] {
  let body: string[];
  try {
    const raw = readFileSync(filePath, "utf8");
    const allLines = raw.split("\n");
    body = allLines.slice(0, maxLines);
    if (allLines.length > maxLines) {
      body.push("", `… ${allLines.length - maxLines} more lines (see ${filePath})`);
    }
  } catch {
    body = [`(could not read ${filePath})`];
  }
  return cardLines(title, body);
}

/** Read `map.get(key)` whether `map` is a Map or a JSON-deserialized plain object. */
function lookup<T>(map: unknown, key: string): T | undefined {
  if (map instanceof Map) return map.get(key) as T | undefined;
  if (map && typeof map === "object") return (map as Record<string, T>)[key];
  return undefined;
}

interface QuizQuestionish {
  id: string;
  level?: string;
  type?: string;
  question: string;
}

interface Quizish {
  topic: string;
  questions: QuizQuestionish[];
}

export interface QuizCardStateish {
  answers?: unknown;
  objectiveResults?: unknown;
  openEndedGrades?: unknown;
}

const QUESTION_GLYPH = {
  unanswered: "○",
  answered: "●",
  correct: "✓",
  incorrect: "✗",
  pending_grade: "…",
} as const;

function questionStatus(q: QuizQuestionish, state: QuizCardStateish): keyof typeof QUESTION_GLYPH {
  const graded = lookup<{ verdict?: string }>(state.openEndedGrades, q.id);
  if (graded?.verdict) {
    if (graded.verdict === "correct") return "correct";
    if (graded.verdict === "incorrect") return "incorrect";
    return "answered";
  }
  const objective = lookup<boolean>(state.objectiveResults, q.id);
  if (objective !== undefined) return objective ? "correct" : "incorrect";
  const answer = lookup<string>(state.answers, q.id);
  const isOpenEnded = q.type === "short_answer" || q.type === "transfer";
  if (isOpenEnded && answer !== undefined) return "pending_grade";
  return answer !== undefined ? "answered" : "unanswered";
}

export function quizCardLines(quiz: Quizish, state: QuizCardStateish = {}): string[] {
  const body: string[] = [];
  let correct = 0;
  let graded = 0;
  for (const q of quiz.questions ?? []) {
    const status = questionStatus(q, state);
    if (status === "correct") correct++;
    if (status === "correct" || status === "incorrect") graded++;
    body.push(`${QUESTION_GLYPH[status]} ${q.level ? `[${q.level}] ` : ""}${q.question}`);
    const answer = lookup<string>(state.answers, q.id);
    if (answer) body.push(`   your answer: ${answer}`);
    const note = lookup<{ note?: string }>(state.openEndedGrades, q.id)?.note;
    if (note) body.push(`   feedback: ${note}`);
  }
  if (graded > 0) body.unshift(`Score: ${correct}/${graded}`, "");
  return cardLines(`Quiz: ${quiz.topic}`, body);
}

interface GoalStepish {
  order: number;
  title: string;
  kind?: string;
  status: string;
}

interface Goalish {
  title: string;
  description?: string;
  status: string;
  steps: GoalStepish[];
  id?: string;
}

const GOAL_STEP_GLYPH: Record<string, string> = {
  not_started: "[ ]",
  in_progress: "[~]",
  done: "[x]",
};

export function goalCardLines(goal: Goalish): string[] {
  const total = goal.steps?.length ?? 0;
  const done = (goal.steps ?? []).filter((s) => s.status === "done").length;
  const percent = total === 0 ? 0 : Math.round((done / total) * 100);
  const nextStep = (goal.steps ?? []).find((s) => s.status !== "done");

  const body: string[] = [];
  if (goal.description) body.push(goal.description, "");
  body.push(`Progress: ${percent}% (${done}/${total})`, `Status: ${goal.status}`);
  if (nextStep) body.push(`Next: ${nextStep.title}`);
  body.push("");
  for (const step of goal.steps ?? []) {
    body.push(`${GOAL_STEP_GLYPH[step.status] ?? "[ ]"} ${step.order + 1}. ${step.title}${step.kind ? ` (${step.kind})` : ""}`);
  }
  return cardLines(`Goal: ${goal.title}`, body);
}

export function goalListCardLines(goals: Goalish[]): string[] {
  if (!goals || goals.length === 0) return cardLines("Learner Goals", ["No goals yet."]);
  const body = goals.map((g) => {
    const total = g.steps?.length ?? 0;
    const done = (g.steps ?? []).filter((s) => s.status === "done").length;
    return `${g.status === "completed" ? "✓" : "•"} ${g.id ? `[${g.id}] ` : ""}${g.title} — ${done}/${total} steps (${g.status})`;
  });
  return cardLines("Learner Goals", body);
}

const ARTIFACT_TOOL_CARDS: Record<string, { title: string; pathKey: string }> = {
  plan: { title: "Lesson Plan", pathKey: "planPath" },
  map: { title: "Concept Map", pathKey: "mmdPath" },
  verify: { title: "Verification Checklist", pathKey: "checklistPath" },
  animate: { title: "Animation Storyboard", pathKey: "storyboardPath" },
};

/**
 * Map a finished tool execution to card lines. Returns undefined when the
 * tool has no card representation (callers fall back to plain text).
 */
export function toolResultCardLines(toolName: string, result: unknown): string[] | undefined {
  const details = (result as { details?: Record<string, unknown> } | undefined)?.details;
  if (!details) return undefined;

  if ((toolName === "quiz" || toolName === "grade_quiz") && details.quiz) {
    return quizCardLines(details.quiz as Quizish, {
      answers: details.answers,
      objectiveResults: details.objectiveResults,
      openEndedGrades: details.openEndedGrades,
    });
  }

  const artifact = ARTIFACT_TOOL_CARDS[toolName];
  if (artifact) {
    const path = details[artifact.pathKey];
    if (typeof path === "string") return artifactPreviewLines(artifact.title, path);
  }

  if (details.goal && typeof details.goal === "object") {
    return goalCardLines(details.goal as Goalish);
  }
  if (Array.isArray(details.goals)) {
    return goalListCardLines(details.goals as Goalish[]);
  }

  if (toolName === "web_search" && Array.isArray(details.citations)) {
    const citations = details.citations as Array<{ title?: string; url?: string }>;
    const body = citations.map((c, i) => `${i + 1}. ${c.title ?? c.url ?? ""}${c.title && c.url ? ` — ${c.url}` : ""}`);
    const query = typeof details.query === "string" ? details.query : "";
    return cardLines(`Web Search: ${query}`, body.length > 0 ? body : ["(no sources)"]);
  }

  return undefined;
}

import { toolResultCardLines } from "../core/cards.js";

/**
 * Renderer-free controller for RPC hosts. Translates pi RPC events into
 * calls on a HostSurface, and services extension UI requests (select,
 * confirm, input, editor) by presenting them through the surface and
 * sending extension_ui_response commands back. The OpenTUI host implements
 * HostSurface with real widgets; tests implement it with scripted answers.
 */

export interface HostSurface {
  /** Append a completed transcript entry (user turn, assistant turn, notice, or card). */
  appendTurn(text: string): void;
  /** Replace the in-progress streaming assistant text (null clears it). */
  setStreaming(text: string | null): void;
  setStatus(text: string): void;
  setBusy(busy: boolean): void;
  setEditorText(text: string): void;
  setWidget(key: string, lines: string[] | undefined, placement?: string): void;
  setTitle(title: string): void;
  /** Resolve with the chosen option string, or undefined when cancelled. */
  presentSelect(title: string, options: string[]): Promise<string | undefined>;
  /** Resolve with the decision, or undefined when cancelled. */
  presentConfirm(title: string, message: string): Promise<boolean | undefined>;
  presentInput(title: string, placeholder?: string): Promise<string | undefined>;
  presentEditor(title: string, prefill?: string): Promise<string | undefined>;
}

export interface HostClientLike {
  onEvent(listener: (event: unknown) => void): unknown;
}

interface UiRequestEvent {
  type: "extension_ui_request";
  id?: string;
  method?: string;
  title?: string;
  options?: string[];
  message?: string;
  placeholder?: string;
  prefill?: string;
  statusText?: string;
  text?: string;
  widgetKey?: string;
  widgetLines?: string[];
  widgetPlacement?: string;
}

function messageText(message: unknown): string {
  const content = (message as { content?: unknown } | null)?.content;
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .map((part) => {
      if (!part || typeof part !== "object") return "";
      const candidate = part as { type?: string; text?: string };
      return candidate.type === "text" && typeof candidate.text === "string" ? candidate.text : "";
    })
    .filter(Boolean)
    .join("\n");
}

function briefArgs(args: unknown): string {
  if (!args || typeof args !== "object") return "";
  const entries = Object.entries(args as Record<string, unknown>)
    .filter(([, value]) => typeof value === "string" || typeof value === "number" || typeof value === "boolean")
    .slice(0, 3)
    .map(([key, value]) => {
      const text = String(value);
      return `${key}=${text.length > 40 ? `${text.slice(0, 40)}…` : text}`;
    });
  return entries.join(", ");
}

export class HostController {
  private client: HostClientLike;
  private surface: HostSurface;
  /** Serializes UI requests: pi awaits each dialog, but never assume only one is outstanding. */
  private uiQueue: Promise<void> = Promise.resolve();

  constructor(client: HostClientLike, surface: HostSurface) {
    this.client = client;
    this.surface = surface;
  }

  attach(): void {
    this.client.onEvent((event) => this.handleEvent(event));
  }

  private async sendUiResponse(requestId: string, response: Record<string, unknown>): Promise<void> {
    const internal = this.client as unknown as { send(command: Record<string, unknown>): Promise<unknown> };
    await internal.send({ type: "extension_ui_response", id: requestId, ...response });
  }

  handleEvent(event: unknown): void {
    const candidate = event as { type?: string } | null;
    if (!candidate || typeof candidate !== "object") return;

    switch (candidate.type) {
      case "message_update": {
        const message = (event as { message?: { role?: string } }).message;
        if (message?.role === "assistant") {
          const text = messageText(message);
          if (text) this.surface.setStreaming(`Keating\n${text}`);
        }
        return;
      }
      case "message_end": {
        const message = (event as { message?: { role?: string } }).message;
        if (message?.role === "assistant") {
          this.surface.setStreaming(null);
          const text = messageText(message);
          if (text) this.surface.appendTurn(`Keating\n${text}`);
        }
        return;
      }
      case "tool_execution_start": {
        const { toolName, args } = event as { toolName?: string; args?: unknown };
        if (toolName) {
          const summary = briefArgs(args);
          this.surface.appendTurn(`→ ${toolName}${summary ? `(${summary})` : ""}`);
        }
        return;
      }
      case "tool_execution_end": {
        const { toolName, result, isError } = event as { toolName?: string; result?: unknown; isError?: boolean };
        if (!toolName) return;
        if (isError) return;
        const card = toolResultCardLines(toolName, result);
        if (card) this.surface.appendTurn(card.join("\n"));
        return;
      }
      case "agent_start":
        this.surface.setBusy(true);
        return;
      case "agent_end":
        this.surface.setBusy(false);
        return;
      case "extension_ui_request":
        this.handleUiRequest(event as UiRequestEvent);
        return;
      default:
        return;
    }
  }

  private handleUiRequest(request: UiRequestEvent): void {
    switch (request.method) {
      case "notify":
        if (request.message) this.surface.appendTurn(`[Keating] ${request.message}`);
        return;
      case "setStatus":
        this.surface.setStatus(request.statusText || "Ready");
        return;
      case "set_editor_text":
        if (typeof request.text === "string") this.surface.setEditorText(request.text);
        return;
      case "setWidget":
        if (request.widgetKey) this.surface.setWidget(request.widgetKey, request.widgetLines, request.widgetPlacement);
        return;
      case "setTitle":
        if (request.title) this.surface.setTitle(request.title);
        return;
      case "select":
      case "confirm":
      case "input":
      case "editor":
        if (request.id) this.enqueueDialog(request as UiRequestEvent & { id: string });
        return;
      default:
        return;
    }
  }

  private enqueueDialog(request: UiRequestEvent & { id: string }): void {
    this.uiQueue = this.uiQueue
      .then(() => this.presentDialog(request))
      .catch((error) => {
        this.surface.appendTurn(`[Keating] UI request failed: ${error instanceof Error ? error.message : String(error)}`);
      });
  }

  private async presentDialog(request: UiRequestEvent & { id: string }): Promise<void> {
    const title = request.title ?? "";
    try {
      switch (request.method) {
        case "select": {
          const value = await this.surface.presentSelect(title, request.options ?? []);
          await this.sendUiResponse(request.id, value === undefined ? { cancelled: true } : { value });
          return;
        }
        case "confirm": {
          const confirmed = await this.surface.presentConfirm(title, request.message ?? "");
          await this.sendUiResponse(request.id, confirmed === undefined ? { cancelled: true } : { confirmed });
          return;
        }
        case "input": {
          const value = await this.surface.presentInput(title, request.placeholder);
          await this.sendUiResponse(request.id, value === undefined ? { cancelled: true } : { value });
          return;
        }
        case "editor": {
          const value = await this.surface.presentEditor(title, request.prefill);
          await this.sendUiResponse(request.id, value === undefined ? { cancelled: true } : { value });
          return;
        }
        default:
          await this.sendUiResponse(request.id, { cancelled: true });
      }
    } catch (error) {
      await this.sendUiResponse(request.id, { cancelled: true }).catch(() => {});
      throw error;
    }
  }
}

